    literature="Pjetër Bogdani (author of 'Cuneus Prophetarum' in 1685 - first original prose book in Albanian), Anton Pashku, Ali Podrimja (esteemed modernist poet), Rexhep Qosja, Azem Shkreli.",
    cinema="New Wave of Kosovar Cinema (historic international acclaim): Blerta Basholli's 'Hive' (Zgjoi - historic triple Sundance Film Festival winner 2021), Kaltrina Krasniqi's 'Vera Dreams of the Sea' (Venice Film Festival), Samir Karahoda (Cannes nominee for 'Displaced').",
    sports="Judo (undisputed global superpower per capita under master coach Driton Kuka: three Olympic Gold medals: Majlinda Kelmendi - Rio 2016, Distria Krasniqi - Tokyo 2020 Gold and Paris 2024 Silver, Nora Gjakova - Tokyo 2020 Gold; Laura Fazliu - Paris 2024 Bronze), Football (Kosovo national team 'Dardanët' in UEFA/FIFA; Vedat Muriqi, Milot Rashica, Amir Rrahmani), Boxing (historic champion Luan Krasniqi).",
    media="RTK (Radio Television of Kosovo - public broadcaster: RTK 1, RTK 2, RTK 3), Koha Ditore, Kohavision (KTV), RTV Dukagjini, Klan Kosova, Telegrafi.com.",
    clothing="Traditional Albanian highlander attire: white woolen skullcap (Plis / Qeleshe), white felt tight trousers with black braiding (Tirq), gold-embroidered velvet vests (Jelek), and colorful embroidered aprons; stylish cosmopolitan European urban street style in Pristina.",
    holidays=["Independence Day (February 17)", "Constitution Day (April 9)", "Europe Day (May 9 - official public holiday)", "Eid al-Fitr (Bajrami i Madh) and Eid al-Adha (Kurban Bajrami)", "Catholic and Orthodox Christmas and Easter"],
    crafts="Prizren silver filigree (intricate lace-like jewelry woven from pure silver wires - UNESCO national heritage), traditional woodcarving, weaving of woolen rugs (Qilim), crafting of wooden Çifteli lutes.",
    worldHeritageSites=["Medieval Monuments in Kosovo (2004/2006 - Visoki Dečani Monastery, Our Lady of Ljeviš, Patriarchate of Peć Monastery, and Gračanica Monastery)"],
